      if(q<0.45) return;
      var k3=0.16*(1-Math.abs(q-0.7)/0.3);
      if(k3<=0) return;
      t.g[idx]=Math.min(255,t.g[idx]+36*k3); t.b[idx]=Math.min(255,t.b[idx]+30*k3);
