  p.fill(0);
  var rotCol=Math.round((rot/360)*MO_TW)%MO_TW; if(rotCol<0) rotCol+=MO_TW;
  var TW=MO_TW, Gc=G.col, Gr=G.row, Gz=G.nz, X0=G.x0, X1=G.x1, ST=G.st;
  var norm=1/moLimbDark(1);
