    var ph = opt.phase == null ? 180 : ((opt.phase % 360) + 360) % 360;
    var pb = Math.round(ph / 6) * 6;                /* 6° of phase */
    var sb = Math.round(((opt.spinDeg || 0) % 360) / 24) * 24;   /* 24° of spin */
    var key = name + "|" + rb + "|" + pb + "|" + sb;
    if (CACHE[key]) return CACHE[key];
